using Microsoft.EntityFrameworkCore;
using Nafadh_Backend.Enums;
using Nafadh_Backend.Models;

namespace Nafadh_Backend.Repositories
{
    public class FeedbackRepository : IFeedbackRepository
    {
        private readonly Nafadhcontext _context;

        public FeedbackRepository(Nafadhcontext context)
        {
            _context = context;
        }

        public async Task<List<NFD_FeedbackCriterion>> GetCriteriaAsync(NFD_FeedbackType? appliesTo)
        {
            var query = _context.NFD_FeedbackCriteria.AsQueryable();

            if (appliesTo.HasValue)
                query = query.Where(c => c.AppliesTo == appliesTo.Value);

            return await query.OrderBy(c => c.OrderIndex).ToListAsync();
        }

        public async Task<NFD_Feedback> AddFeedbackAsync(NFD_Feedback feedback)
        {
            await _context.NFD_Feedbacks.AddAsync(feedback);
            await _context.SaveChangesAsync();
            return feedback;
        }

        public async Task<List<NFD_Feedback>> GetByTrainerAsync(int trainerId)
        {
            return await _context.NFD_Feedbacks
                .Include(f => f.Scores)
                    .ThenInclude(s => s.Criterion)
                .Where(f => f.Type == NFD_FeedbackType.TrainerRating && f.TrainerId == trainerId)
                .ToListAsync();
        }

        public async Task<List<NFD_Feedback>> GetByBatchAsync(int batchId)
        {
            return await _context.NFD_Feedbacks
                .Include(f => f.Scores)
                    .ThenInclude(s => s.Criterion)
                .Where(f => f.Type == NFD_FeedbackType.BatchExperienceRating && f.BatchId == batchId)
                .ToListAsync();
        }

        public async Task<bool> HasSubmittedAsync(int traineeId, int moduleId, NFD_FeedbackType type)
        {
            return await _context.NFD_Feedbacks
                .AnyAsync(f => f.TraineeId == traineeId && f.ModuleId == moduleId && f.Type == type);
        }
    }
}
